#include "core/log.h"

int main() {
    Logger logger{};
    return logger.clock.size();
}

#include "core/str.h"
#include "feature/hook.h"

int length(const Str& s) {
    return s.n + hook(nullptr);
}

#pragma once

struct Str {
    int n;
};

int length(const Str& s);

#include "feature/hook.h"
#include "core/log.h"

int hook(Logger* logger) {
    return logger ? logger->clock.size() : 0;
}

#pragma once

struct Logger;

int hook(Logger* logger);

#pragma once
#include "core/str.h"

struct Clock {
    Str name;

    int size() const {
        return length(name);
    }
};

